mod audio;mod game;mod video;use game::Game;
fn main(){let mut captures=vec![];let mut seed=0x764d120a_u32;for case in 0..200 {let mut types=[0u8;16];let mut states=[0u8;16];for i in 0..16 {seed=seed.wrapping_mul(1664525).wrapping_add(1013904223);types[i]=match case {0=>0,1=>1,2=>0x81,_=>[0,1,2,52,54,57,0x81,0xb6][((seed>>20)&7)as usize]};if case>2 && seed&1024!=0 {states[i]=128;}}for priority in [false,true] {let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x27]=6;for i in 0..16 {g.memory[0x720+i]=types[i];g.memory[0x520+i]=states[i];}g.actor_call(0xf25b,0).unwrap();if g.x==255 && priority {g.actor_call(0xf1ec,0).unwrap();}captures.push(serde_json::json!({"case":case,"types":types,"offscreen":states.map(|v|v!=0),"priority":priority,"selected":if g.x==255{None}else{Some(g.x)}}));}}println!("{}",serde_json::to_string(&captures).unwrap());}
